"""Quick clinic re-checks that keep the clinic database up to date.

1. Download the clinic's page (a few seconds; no browser agent, no TinyFish credits).
2. If the page text is the same as at the last check, the stored result still holds: done.
3. Otherwise Gemini reads the text (following one "new patients" link if the page itself doesn't say).
4. Only when the page can't be read (blocked, JavaScript-only, or silent) does a TinyFish browser agent take over.
A status change triggers Watchdog alerts for everyone watching that clinic.
"""
import asyncio
import hashlib
import json
import re
import time
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse

import httpx

from . import config, common, llm, models, clinic_db, scanning, watchdog

USER_AGENT = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36 CareScout/1.0"
FETCH_TIMEOUT_S = 15
MIN_TEXT_CHARS = 300  # less than this usually means the page is built by JavaScript
MAX_PROMPT_CHARS = 12000
SKIP_TAGS = {"script", "style", "noscript", "svg", "template", "iframe"}
BLOCK_TAGS = {"p", "div", "br", "li", "h1", "h2", "h3", "h4", "h5", "h6", "tr", "section", "article", "header", "footer", "main", "nav"}
KEYWORDS = ("new patient", "accepting", "waitlist", "wait list", "waiting list", "not accepting", "no longer accepting",
            "roster", "registration", "register", "intake", "currently full", "practice is full")
LINK_HINTS = ("patient", "waitlist", "wait-list", "wait list", "register", "registration", "intake", "join", "apply",
              "form", "become", "accepting", "enrol", "enroll")


class PageReadError(Exception):
    """The page couldn't be read quickly (the browser agent may still manage)."""


# ---------- reading a page ----------

class _PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts: list[str] = []
        self.links: list[tuple[str, str]] = []
        self.title = ""
        self._skip = 0
        self._in_title = False
        self._href: str | None = None
        self._link_text: list[str] = []

    def handle_starttag(self, tag, attrs):
        if tag in SKIP_TAGS:
            self._skip += 1
        elif tag == "title":
            self._in_title = True
        elif tag == "a":
            self._href = dict(attrs).get("href")
            self._link_text = []
        if tag in BLOCK_TAGS:
            self.parts.append("\n")

    def handle_endtag(self, tag):
        if tag in SKIP_TAGS and self._skip:
            self._skip -= 1
        elif tag == "title":
            self._in_title = False
        elif tag == "a" and self._href is not None:
            self.links.append((self._href, " ".join(t for t in self._link_text if t)))
            self._href = None
        if tag in BLOCK_TAGS:
            self.parts.append("\n")

    def handle_data(self, data):
        if self._in_title:
            self.title += data
        elif not self._skip:
            self.parts.append(data)
            if self._href is not None:
                self._link_text.append(data.strip())


def read_html(html: str, base_url: str) -> tuple[str, list[dict], str]:
    """Visible text, links ({text, url}) and title of an HTML page."""
    p = _PageParser()
    try:
        p.feed(html)
        p.close()
    except Exception:
        pass  # a broken page: use whatever was parsed
    text = re.sub(r"[ \t\r\f\v ]+", " ", "".join(p.parts))
    text = re.sub(r"\s*\n\s*", "\n", text).strip()
    seen, links = set(), []
    for href, label in p.links:
        href = (href or "").strip()
        if not href or href.startswith(("#", "mailto:", "tel:", "javascript:")):
            continue
        url = urljoin(base_url, href).split("#")[0]
        if not common.is_http_url(url) or url in seen:
            continue
        seen.add(url)
        links.append({"text": re.sub(r"\s+", " ", label).strip()[:80], "url": url})
    return text, links, re.sub(r"\s+", " ", p.title).strip()[:200]


def relevant_links(links: list[dict], limit: int = 25) -> list[dict]:
    hits = [l for l in links if any(h in (l["text"] + " " + l["url"]).lower() for h in LINK_HINTS)]
    return hits[:limit]


def focus(text: str) -> str:
    """Trim long pages to what matters: the start of the page plus the passages around availability keywords."""
    if len(text) <= MAX_PROMPT_CHARS:
        return text
    lower = text.lower()
    spans = []
    for kw in KEYWORDS:
        for m in re.finditer(re.escape(kw), lower):
            spans.append((max(0, m.start() - 500), min(len(text), m.end() + 700)))
    spans.sort()
    merged: list[list[int]] = []
    for s, e in spans:
        if merged and s <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    out, budget = [text[:3000]], MAX_PROMPT_CHARS - 3000
    for s, e in merged:
        if s < 3000:
            s = 3000
        if e <= s or budget <= 0:
            continue
        piece = text[s:e][:budget]
        out.append(piece)
        budget -= len(piece)
    return "\n...\n".join(out)


def _norm(s: str) -> str:
    return re.sub(r"[^a-z0-9]+", " ", (s or "").lower()).strip()


"""Gemini Triage: rank, translate and add call scripts / badges: POST /api/rank."""
import json

from fastapi import APIRouter, HTTPException

from . import config, llm, models

router = APIRouter()


@router.post("/api/rank")
def rank(req: models.RankRequest):
    if not req.clinics:
        return {"ranked_clinics": []}
    prompt = (
        "You rank Ontario family-doctor clinics for a patient.\n"
        f"Patient preferences: {json.dumps(req.preferences)}\n"
        f"Patient coverage type: {req.coverage_type}\n"
        f"Patient language: {req.language}\n"
        f"Clinics (scan results): {json.dumps(req.clinics)}\n\n"
        "Return every clinic, best first. For each: name (exactly as in the input, never translated), "
        "url (exactly as in the input), "
        "score (integer 0-100; clinics accepting new patients score highest, waitlist middle, closed lowest; "
        f"boost clinics whose notes show they accept {req.coverage_type} patients or offer service in {req.language}; "
        "lower clinics whose notes say they do not accept that coverage type), "
        "reason (one sentence), requirements (list of things the patient needs to join, from the notes; "
        "empty list if none), next_step (one short action the patient should take), "
        "coverage_tags (short badges based only on the clinic's notes, e.g. [\"OHIP\", \"Nurse Practitioner\"], "
        "[\"UHIP Friendly\"], or [\"Check Eligibility\"] when the notes do not say). "
        "phone_number (the clinic's phone number copied from raw_notes or evidence_quote, else null), "
        "call_hours (when to call, e.g. \"Mon-Fri, 8am-4pm\", from the notes, else null), "
        "call_script (ONLY when the clinic's waitlist_url is null, else null: a natural 2-3 sentence phone script "
        f"in {req.language} the patient can read word for word to ask about joining as a new patient, "
        f"then a blank line, then a heading meaning 'Have ready:' written in {req.language} "
        "(do not leave it in English unless the language is English), then a short "
        "checklist with one item per line, each starting with '- ', of what to have in hand before dialing "
        f"(such as their {req.coverage_type} card, postal code, date of birth, current medications). "
        "Separate the script, heading and checklist lines with real line breaks. "
        f"Write reason, requirements, next_step and call_script naturally in {req.language}. "
        "Keep clinic names, URLs, phone numbers and coverage_tags in English. "
        "Never invent a phone number or hours; use null if the data does not contain them. Use only the given data. "
        "If a clinic has distance_km, that is the straight-line distance from the PATIENT'S HOME (their postal code), "
        "not from downtown or any landmark: prefer closer clinics when other factors are similar, and when you mention it "
        "say it is that far from the patient's home. "
        "If a website is a directory, referral service or list of doctors rather than a clinic the patient can join "
        "directly, give it at most 30, say in reason that it is a directory and not a clinic, and make next_step using it "
        "to find a clinic. "
        "If a clinic's raw_notes starts with 'scan failed' or 'scan error', its website could not be checked: "
        "give it score 10, say in reason that its status could not be checked, and make next_step visiting its website "
        "or calling; never claim it is closed. "
        "If a clinic has expired: true, its status was last confirmed status_age_days days ago and may have changed: "
        "give it at most 40, say in reason when it was last confirmed and that it needs a re-check, make next_step "
        "checking the clinic's website or calling, and never present that status as current."
    )
    config.require_key("GEMINI_API_KEY")  # a missing key is a JSON 500, not a 502
    try:
        ranked = llm.generate_json(prompt, models.RankResponse)  # retries + backup model when Gemini is overloaded
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"rank failed: {str(e)[:300]}")
    clinics = [c.model_dump() for c in ranked.ranked_clinics]
    # Fill url from the input clinics (trust our data, not the model): exact name, then case-insensitive name,
    # then the model's url if it really is one of the input urls.
    input_urls = {str(c.get("url")) for c in req.clinics if c.get("url")}
    by_name = {str(c.get("name")): c.get("url") for c in req.clinics if c.get("name")}
    by_lower = {k.strip().lower(): v for k, v in by_name.items()}
    for c in clinics:
        c["score"] = max(0, min(100, c["score"]))
        c["url"] = by_name.get(c["name"]) or by_lower.get(c["name"].strip().lower()) or (c["url"] if c["url"] in input_urls else None)
    return {"ranked_clinics": sorted(clinics, key=lambda c: -c["score"])}
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { Bot, MapPinned, Sparkles } from "lucide-react";
import { useAppState } from "../state/AppState";
import { mergeClinics } from "../lib/clinics";
import MissionForm from "../components/MissionForm";
import AgentFeed from "../components/AgentFeed";
import ClinicMap from "../components/ClinicMap";
import ClinicCard from "../components/ClinicCard";
import ApplyModal from "../components/ApplyModal";
import ErrorBoundary from "../components/ErrorBoundary";
import { useFlip } from "../hooks/useFlip";

function EmptyState() {
  const steps = [
    { icon: MapPinned, title: "Find the clinics", text: "Searches your city for family practices." },
    { icon: Bot, title: "Read every website", text: "Agents check who's accepting new patients." },
    { icon: Sparkles, title: "Rank them for you", text: "Sorted for your coverage, language and distance." },
  ];
  return (
    <div className="card animate-card-in p-8">
      <h2 className="text-xl font-bold">Your results will appear here</h2>
      <p className="mt-1 text-sm text-slate-500">
        Press <b className="text-ink">Launch CareScout</b> to start. A live search takes a few minutes; Demo mode shows saved results instantly.
      </p>
      <ol className="mt-6 grid gap-4 sm:grid-cols-3">
        {steps.map(({ icon: Icon, title, text }, i) => (
          <li key={title} className="rounded-xl bg-slate-50 p-4">
            <div className="flex items-center gap-2 text-sm font-semibold text-ink">
              <span className="flex h-6 w-6 items-center justify-center rounded-full bg-ink text-xs text-paper">{i + 1}</span>
              {title}
            </div>
            <div className="mt-2 flex items-start gap-2 text-xs text-slate-500">
              <Icon className="h-4 w-4 shrink-0 text-pine-600" />
              {text}
            </div>
          </li>
        ))}
      </ol>
    </div>
  );
}

export default function FindPage() {
  const { search, setSearch, mission, launch, refreshWatchCount, publicDemo } = useAppState();
  const { state, stop, reset } = mission;
  const [params, setParams] = useSearchParams();
  const [selectedUrl, setSelectedUrl] = useState(null);
  const [applyFor, setApplyFor] = useState(null);
  const cardRefs = useRef({});
  const email = search.email.trim();

  const clinics = useMemo(() => mergeClinics(state.scanned, state.urls, state.ranked), [state.scanned, state.urls, state.ranked]);
  // cards glide to their ranked position when ranking arrives
  useFlip(clinics.map((c) => c.url), cardRefs);

  // /find?demo=1 (from the home page): switch on Demo mode and run it straight away (once).
  const demoStarted = useRef(false);
  useEffect(() => {
    if (params.get("demo") === "1" && !demoStarted.current) {
      demoStarted.current = true;
      setParams({}, { replace: true });
      setSearch((s) => ({ ...s, useCache: true }));
      if (!state.running) launch({ useCache: true });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onLaunch = () => {
    setSelectedUrl(null);
    launch();
  };

  const selectClinic = useCallback((url) => {
    setSelectedUrl(url);
    cardRefs.current[url]?.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }, []);

  return (
    <div className="container-page space-y-4 py-8">
      <div className="mb-2">
        <h1 className="text-3xl font-bold tracking-tight">Find a family doctor</h1>
        <p className="mt-1 text-slate-500">Tell CareScout where you are and what you need. Agents check each clinic's website for you.</p>
      </div>

      <MissionForm values={search} onChange={setSearch} onLaunch={onLaunch} onStop={stop} running={state.running} publicDemo={publicDemo} />
      <AgentFeed state={state} onStop={stop} onReset={reset} />

      {clinics.length > 0 ? (
        <div className="grid grid-cols-1 gap-4 lg:grid-cols-5">
          <div className="min-w-0 lg:col-span-2">
            <div className="h-[360px] lg:sticky lg:top-24 lg:h-[calc(100vh-8rem)]">
              <ErrorBoundary label="The map">
                <ClinicMap clinics={clinics} selectedUrl={selectedUrl} onSelect={selectClinic} />
              </ErrorBoundary>
            </div>
          </div>
          <div className="min-w-0 space-y-3 lg:col-span-3">
            {clinics.map((c, i) => (
              <ErrorBoundary key={c.url} label={`The card for ${c.name || c.url}`}>
                <ClinicCard
                  ref={(el) => (cardRefs.current[c.url] = el)}
                  clinic={c}
                  enterDelay={Math.min(i, 8) * 45}
                  selected={c.url === selectedUrl}
                  onSelect={setSelectedUrl}
                  onApply={setApplyFor}
                  email={email}
                  city={search.city}
                  onWatched={refreshWatchCount}
                />
              </ErrorBoundary>
            ))}
          </div>
        </div>
      ) : (
        !state.running && state.log.length === 0 && <EmptyState />
      )}

      {applyFor && <ApplyModal clinic={applyFor} defaults={search} onClose={() => setApplyFor(null)} />}
    </div>
  );
}
